import { applyIni, patchIni, settingsToIni } from './config.js';
import { plans, currentBlock, intervalTarget } from './training.js';
import { BridgeUI } from './bridge-ui.js';
let bridgeUi=null;
const activityId=()=>globalThis.crypto?.randomUUID?.()??('activity-'+Date.now()+'-'+Math.random().toString(36).slice(2));
const $=s=>document.querySelector(s);
const icons={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',training:'<path d="m3 17 5-9 4 12 5-16 4 10"/>',history:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7M12 7v5l3 2"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',power:'<path d="m13 2-9 12h7l-1 8 10-13h-7z"/>',speed:'<path d="M4 19a9 9 0 1 1 16 0M12 13l4-5M5 13h1m12 0h1M8 7l1 1"/>',cadence:'<path d="M4 10a8 8 0 0 1 14-4l2 3M20 3v6h-6M20 14a8 8 0 0 1-14 4l-2-3M4 21v-6h6"/>',heart:'<path d="M20 5c-3-3-7 0-8 2-1-2-5-5-8-2-4 4 1 9 8 15 7-6 12-11 8-15Z"/>',bike:'<circle cx="5.5" cy="16.5" r="4"/><circle cx="18.5" cy="16.5" r="4"/><path d="m6 16 5-9 7 9M8 7h5m2-4h3l2 7"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',play:'<path d="m8 4 13 8-13 8z"/>',pause:'<path d="M8 5v14M16 5v14"/>',stop:'<rect x="5" y="5" width="14" height="14" rx="1"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',check:'<path d="m5 12 4 4L19 6"/>',sensor:'<path d="m9 4 8 8-8 8V4Zm0 8L5 8m4 4-4 4"/>',mountain:'<path d="m2 20 8-16 5 10 3-5 5 11H2Zm5-10 3 2 3-2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 16v5h16v-5"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.bike}</svg>`;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=0)=>Number(v||0).toLocaleString('es-CO',{maximumFractionDigits:d,minimumFractionDigits:d});
const time=s=>{s=Math.floor(s);return `${Math.floor(s/3600)?Math.floor(s/3600)+':':''}${String(Math.floor(s/60)%60).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;};
const date=d=>new Date(d).toLocaleDateString('es-CO',{day:'numeric',month:'short'});
const load=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const defaults={weight:75,ftp:240,difficulty:100,resistance:true,bike:'Road',bots:[1,0,0],traffic:50,behavior:'NORMAL',devices:{FECDeviceId:'0',PWRDeviceId:'0',HRDeviceId:'0',CADDeviceId:'0',BFTMSDeviceAddr:'0',BPWRDeviceAddr:'0',BHRDeviceAddr:'0',BCADDeviceAddr:'0'}};
let settings={...defaults,...load('gtbv-settings',{})};
let iniText=load('gtbv-ini',''); let iniName=load('gtbv-ini-name','');
let activities=load('gtbv-activities',[]); let page='dashboard',filter='all',zoom=1,activeWorkout=0,erg=true,target=180;
let session={state:'idle',seconds:0,distance:0,ascent:0,energy:0,points:[],started:null};
const workouts=[{name:'Sweet Spot Builder',desc:'Resistencia que se convierte en progreso.',minutes:45,tags:'Intermedio · 3 × 8 min · 88 % FTP',heights:[25,32,40,78,78,78,35,78,78,78,35,78,78,78,30,24],ratio:.88},{name:'Base aeróbica',desc:'Encuentra tu ritmo. Construye tu base.',minutes:60,tags:'Fácil · Continuo · 65 % FTP',heights:[22,30,40,50,55,55,55,55,55,55,55,55,50,40,30,22],ratio:.65},{name:'Intervalos VO₂',desc:'Esfuerzos cortos para llegar más lejos.',minutes:35,tags:'Avanzado · 5 × 3 min · 115 % FTP',heights:[25,35,90,30,90,30,90,30,90,30,90,30,25,20,17,15],ratio:1.15},{name:'Rodaje libre',desc:'Sin intervalos. Tú eliges el camino.',minutes:0,tags:'Libre · Sin duración · Objetivo manual',heights:[20,30,25,40,32,50,40,35,45,55,40,50,45,35,30,25],ratio:.75}];
const DEMO_POINTS=Array.from({length:100},(_,i)=>({t:i*27,p:Math.round(156+40*Math.sin(i/7)+17*Math.sin(i*1.8)+(i>25&&i<75?32:0))}));
const demoActivities=[{id:'demo-1',name:'Por la costa de Los Santos',date:new Date(Date.now()-864e5).toISOString(),distance:32.6,seconds:3724,power:189,maxPower:412,ascent:326,points:DEMO_POINTS,demo:true},{id:'demo-2',name:'Subida a Vinewood Hills',date:new Date(Date.now()-3*864e5).toISOString(),distance:24.8,seconds:3148,power:205,maxPower:538,ascent:682,points:DEMO_POINTS.map(x=>({...x,p:x.p+16})),demo:true},{id:'demo-3',name:'Una vuelta por el desierto',date:new Date(Date.now()-5*864e5).toISOString(),distance:45.2,seconds:5405,power:172,maxPower:386,ascent:204,points:DEMO_POINTS.map(x=>({...x,p:x.p-17})),demo:true}];
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('El almacenamiento está lleno. Exporta tus datos antes de continuar.');return false}}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function modal(content){$('#modal-body').innerHTML=`<button class="close-dialog" data-action="close" aria-label="Cerrar">×</button>${content}`;$('#modal').showModal();}
function heading(eyebrow,title,sub,action=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action||`<div class="date-note">${icon('calendar')}${new Date().toLocaleDateString('es-CO',{weekday:'short',day:'numeric',month:'long'})}</div>`}</div>`;}
function metric(label,value,unit,name,caption,featured=false){return `<div class="metric ${featured?'featured':''}"><div class="metric-label">${icon(name)}${label}</div><div class="metric-value"><span data-live="${name}">${value}</span><small>${unit}</small></div><div class="metric-caption">${caption}</div><svg class="spark" viewBox="0 0 80 26" fill="none"><path d="M1 20 9 18 15 22 21 14 27 17 33 8 39 12 45 9 50 13 57 5 63 9 71 3 79 6" stroke="${featured?'#d5ec65':'#bdc9a8'}" stroke-width="1.5"/></svg></div>`;}
function chart(points=DEMO_POINTS){const values=points.length?points:[{t:0,p:0},{t:1,p:0}];const max=Math.max(300,...values.map(x=>x.p||0));const maxT=values.at(-1).t||1;const path=values.map((p,i)=>`${i?'L':'M'}${(35+p.t/maxT*520).toFixed(1)},${(112-(p.p||0)/max*94).toFixed(1)}`).join(' ');return `<svg class="chart" viewBox="0 0 570 145" role="img" aria-label="Gráfica de potencia en vatios por tiempo"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#a9bb77" stop-opacity=".3"/><stop offset="1" stop-color="#a9bb77" stop-opacity=".02"/></linearGradient></defs>${[0,1,2,3].map(n=>`<path d="M35 ${18+n*31.3}H555" stroke="#edf0e7" stroke-dasharray="3 4"/><text x="0" y="${22+n*31.3}">${Math.round(max*(1-n/3))}</text>`).join('')}<path d="${path}L555 112H35Z" fill="url(#chart-fill)"/><path d="${path}" fill="none" stroke="#8b9f5c" stroke-width="1.7"/>${[0,1,2,3,4,5].map(n=>`<text x="${35+n*104}" y="136" text-anchor="${n===5?'end':'middle'}">${time(maxT*n/5)}</text>`).join('')}</svg>`;}
function map(){return `<div class="route-map"><svg viewBox="0 0 760 330" preserveAspectRatio="xMidYMid slice" role="img" aria-label="Mapa ilustrativo de una ruta demo por Los Santos"><defs><pattern id="mapgrain" width="7" height="7" patternUnits="userSpaceOnUse"><circle cx="1" cy="2" r=".45" fill="#798369" opacity=".12"/></pattern></defs><g id="map-content" style="transform:scale(${zoom});transform-origin:center"><rect width="760" height="330" fill="#e9ecdf"/><path d="M0 0H158Q143 48 168 83T148 147Q136 176 171 213T194 276L160 330H0Z" fill="#cbdcd7"/><path d="M160 0Q147 48 172 83T153 147Q140 176 175 213T198 276L164 330" fill="none" stroke="#f6f7ee" stroke-width="8"/><g fill="#d7dfc7" opacity=".7"><path d="m308 0 93 29 83-13 53 59-59 43-114-24-62-58z"/><path d="m582 0 178 0v147l-91-12-45-52z"/><path d="m550 195 105-28 105 42v121H551l30-57z"/><path d="m217 210 69 13 40 89-58 18-64-43z"/></g><g fill="none" stroke="#bac6a7" stroke-width=".7" opacity=".5">${Array.from({length:7},(_,i)=>`<path d="M${320+i*12} -10q-32 57 47 62t116 37 109 12T790 ${15+i*16}"/><path d="M${450+i*9} 340q-28-52 71-78t107-58 153-5"/>`).join('')}</g><g fill="#dee4d2" stroke="#d0d9c2" stroke-width=".7"><path d="m206 77 78 2-4 41-64-5z"/><path d="m295 75 55 9-8 41-53-5z"/><path d="m227 139 56-5 3 34-47 16z"/><path d="m302 143 53-5 15 35-53 10z"/><path d="m355 87 48 14 17 34-60-7z"/><path d="m397 151 50-7 11 39-47 10z"/><path d="m316 204 75-11 15 43-68 22z"/><path d="m423 215 71-19 13 34-75 26z"/></g><g stroke="#fafbf6" fill="none" stroke-linecap="round"><path d="M185 0q-21 83 21 128t59 109 30 93" stroke-width="8"/><path d="m212 0 20 73 70-5 43 6 61 27 41 20 51 54 93 5 169-33" stroke-width="7"/><path d="M211 129q102-17 169 2t82 54l-17 145" stroke-width="6"/><path d="m235 194 83-9 70 1 60 5 78 23 54 116" stroke-width="6"/><path d="m288 69 7 68 13 60 25 69 20 64M358 80l-5 58 40 65 9 127M202 266l123 8 99-24 118-28 218 59" stroke-width="5"/><path d="M470 0 4 0M558 0l-45 82-38 49 48 47 111 72 126 5" stroke-width="6"/></g><g fill="none" stroke="#c9bfa6" stroke-width="2.5"><path d="M181 0q-27 96 15 143t53 90 19 97"/><path d="m760 71-85 17-70 59-80 23-65 46-35 114"/></g><path d="M266 251 245 211 226 175 213 138 208 95 231 73 290 68 347 76 394 98 419 131 447 162 452 194 418 205 374 198 329 201 297 224 266 251" fill="none" stroke="#fff" stroke-width="8" stroke-linejoin="round"/><path d="M266 251 245 211 226 175 213 138 208 95 231 73 290 68 347 76 394 98 419 131 447 162 452 194 418 205 374 198 329 201 297 224 266 251" fill="none" stroke="#77924c" stroke-width="4" stroke-linejoin="round"/><g fill="#869378" font-family="DM Sans,sans-serif" font-size="10" letter-spacing="2"><text x="300" y="158">LOS SANTOS</text><text x="430" y="47" font-size="8">VINEWOOD HILLS</text><text x="545" y="292" font-size="8">EL BURRO HEIGHTS</text><text x="196" y="297" font-size="8">VESPUCCI</text></g><text x="66" y="200" fill="#8daba2" font-size="9" font-family="DM Sans,sans-serif" letter-spacing="3" transform="rotate(-74 66 200)">PACIFIC OCEAN</text><circle cx="266" cy="251" r="8" fill="white" stroke="#77924c" stroke-width="2"/><circle cx="266" cy="251" r="3" fill="#77924c"/><circle cx="394" cy="98" r="17" fill="#79944c" opacity=".15"/><circle cx="394" cy="98" r="9" fill="#6d8745" stroke="white" stroke-width="3"/><rect width="760" height="330" fill="url(#mapgrain)" pointer-events="none"/></g></svg><div class="map-tag"><i></i> VISTA DE RUTA · DEMO</div><div class="map-zoom"><button data-action="zoom-in" aria-label="Acercar mapa">+</button><button data-action="zoom-out" aria-label="Alejar mapa">−</button></div></div>`;}
function workoutPanel(){const w=workouts[activeWorkout];const pct=w.minutes?Math.min(100,session.seconds/(w.minutes*60)*100):0;return `<div class="card workout-panel"><div class="workout-top"><p class="eyebrow">TU ENTRENAMIENTO</p><span class="pill lime">${w.minutes?w.minutes+' MIN':'LIBRE'}</span></div><h2>${w.name}</h2><p class="subtitle">${w.desc}</p><div class="workout-bars" aria-label="Perfil de intervalos">${(plans[activeWorkout].length?plans[activeWorkout]:w.heights.map(h=>[1,h/100])).map(([duration,ratio],i)=>`<span style="height:${Math.min(98,ratio/1.2*100)}%;flex:${duration}" class="${ratio>.8?'high':''} ${i===currentBlock(activeWorkout,session.seconds)?'current':''}"></span>`).join('')}</div><div class="workout-progress"><span id="workout-progress" style="width:${pct}%"></span></div><div class="workout-time"><span data-live="elapsed">${time(session.seconds)}</span><span>${w.minutes?w.minutes+':00':'Sin límite'}</span></div><div class="erg-row"><span>Modo ERG <span class="badge-demo">demo</span></span><button class="switch" role="switch" aria-label="Modo ERG" aria-checked="${erg}" data-action="erg"></button></div><div class="target-row"><span>Objetivo de potencia</span><div class="stepper"><button data-action="target-down" aria-label="Reducir 5 vatios">−</button><strong><span data-live="target">${target}</span><small>W</small></strong><button data-action="target-up" aria-label="Aumentar 5 vatios">+</button></div></div><div class="workout-buttons"><button class="btn dark" data-action="session">${icon(session.state==='running'?'pause':'play')}<span>${session.state==='running'?'Pausar sesión':session.state==='paused'?'Continuar':'Iniciar sesión'}</span></button><button class="icon-btn" data-action="finish" aria-label="Finalizar y guardar sesión" ${session.seconds?'':'disabled'}>${icon('stop')}</button></div></div>`;}
function dashboard(){return `${heading('CADA PEDALADA CUENTA','Tu mundo. <em>Tu ritmo.</em>','Sal a explorar Los Santos. Nosotros seguimos tu progreso.')}<div class="live-header"><span class="section-title"><i class="live-dot"></i> Tu actividad, de un vistazo</span><span class="tiny">Datos simulados · <span id="session-status">${session.state==='running'?'Sesión en curso':session.state==='paused'?'En pausa':'Listo para rodar'}</span></span></div><div class="metric-grid">${metric('Potencia','186','W','power','<span id="power-zone">Z2 · Resistencia</span>',true)}${metric('Velocidad','32,4','km/h','speed','Encuentra tu ritmo')}${metric('Cadencia','88','rpm','cadence','Una pedalada a la vez')}${metric('Frecuencia cardíaca','142','bpm','heart','Datos de demostración')}</div><div class="grid-main"><section class="card"><div class="card-header"><div><h2>El camino de hoy</h2><span class="tiny">Un poco de costa. Un poco de ciudad.</span></div><button class="btn ghost" data-action="route" style="min-height:30px;padding:6px 9px">Ver ruta ↗</button></div>${map()}<div class="route-footer"><div class="route-name">Los Santos Coastal Loop<small>Circuito ilustrativo · Carretera</small></div><div class="route-distance"><div>32,6<small>KILÓMETROS</small></div><div>326<small>METROS ↑</small></div></div></div></section>${workoutPanel()}</div><div class="grid-bottom"><section class="card"><div class="card-header"><div><h2>Tu esfuerzo en el tiempo</h2><span class="tiny">Potencia · ${session.seconds?'Sesión actual':'Vista previa de 45 min'}</span></div><div class="chart-legend"><span><i></i> Potencia</span><span>W</span></div></div><div class="chart-wrap" id="live-chart">${chart(session.points.length?session.points:undefined)}</div></section><section class="card"><div class="card-header"><h2>Cada kilómetro suma</h2><span>↗</span></div><div class="session-stats"><div><small>Distancia</small><strong><span data-live="distance" style="font:inherit;color:inherit">${fmt(session.distance,1)}</span> <span>km</span></strong><p>En esta sesión</p></div><div><small>Tiempo</small><strong data-live="elapsed">${time(session.seconds)}</strong><p>Tiempo activo</p></div><div><small>Desnivel</small><strong><span data-live="ascent" style="font:inherit;color:inherit">${Math.round(session.ascent)}</span> <span>m</span></strong><p>Ascenso acumulado</p></div></div><div class="session-note">${icon('bike')}Tu próxima mejor vuelta empieza aquí.</div></section></div>`;}
function selectOptions(values,selected){return values.map(v=>{const [value,label]=Array.isArray(v)?v:[v,v];return `<option value="${escape(value)}" ${String(value)===String(selected)?'selected':''}>${escape(label)}</option>`}).join('');}
const devices=[['trainer','Rodillo inteligente','FECDeviceId','BFTMSDeviceAddr','bike'],['power','Potenciómetro','PWRDeviceId','BPWRDeviceAddr','power'],['heart','Frecuencia cardíaca','HRDeviceId','BHRDeviceAddr','heart'],['cadence','Cadencia','CADDeviceId','BCADDeviceAddr','cadence']];
function configuration(){return `${heading('A TU MEDIDA','Prepara tu <em>próxima vuelta.</em>','Tu perfil y tus preferencias, en un solo lugar.',`<a class="btn ghost" href="https://www.gtbikev.com/content/configuration/" target="_blank" rel="noopener">Documentación ↗</a>`)}<form id="settings-form"><div class="section-grid"><section class="card form-card"><h2>${icon('settings')} Tu perfil de ciclista</h2><p>La base de tu simulación y tus zonas de entrenamiento.</p><div class="form-row"><label class="field">Peso (kg)<input name="weight" type="number" min="25" max="250" step=".1" required value="${settings.weight}"></label><label class="field">FTP (W)<input name="ftp" type="number" min="50" max="600" step="1" required value="${settings.ftp}"></label></div><label class="field">Tipo de bicicleta<select name="bike">${selectOptions([['Road','Carretera'],['Gravel','Gravel'],['Mountain','Montaña'],['Tribike','Contrarreloj'],['Fixie','Fixie'],['Commuter','Urbana'],['BMX','BMX']],settings.bike)}</select></label><label class="field">Trainer Difficulty <span><strong id="difficulty-value">${settings.difficulty}</strong> %</span><input name="difficulty" type="range" min="0" max="100" value="${settings.difficulty}"><span class="range-caption"><span>0 % · Sin pendiente</span><span>100 % · Pendiente completa</span></span></label><label class="setting-row"><span>Control de resistencia<small>Desactívalo para usar control manual (255 en el INI).</small></span><input name="resistance" type="checkbox" ${settings.resistance!==false?'checked':''}></label><p class="tiny">Ajusta la pendiente enviada al rodillo en subidas. La velocidad virtual usa la pendiente real.</p></section><section class="card form-card"><h2>${icon('sensor')} Selección de sensores</h2><p>Configura la búsqueda que hará GTBikeV en el PC.</p>${devices.map(([id,name,ant,ble,ic])=>`<div class="sensor"><span class="sensor-icon">${icon(ic)}</span><div><strong>${name}</strong><small>ANT+ ${settings.devices[ant]==='0'?'automático':settings.devices[ant]==='65535'?'desactivado':escape(settings.devices[ant])} · BLE ${settings.devices[ble]==='0'?'automático':settings.devices[ble]==='FF:FF:FF:FF:FF:FF'?'desactivado':'específico'}</small></div><button type="button" class="btn ghost" data-action="sensor" data-id="${id}">Configurar</button></div>`).join('')}<p class="tiny" style="margin:13px 0 0">La web no empareja dispositivos físicos en esta versión.</p></section><section class="card form-card"><h2>${icon('bike')} Compañeros de ruta</h2><p>Elige hasta cinco bots para acompañarte.</p><label class="field">Número de bots<select name="botCount">${selectOptions([0,1,2,3,4,5],settings.bots.length)}</select></label><div id="bot-fields">${botFields(settings.bots)}</div></section><section class="card form-card"><h2>${icon('speed')} El ambiente de tu ruta</h2><p>Personaliza el tráfico de Los Santos.</p><label class="field">Sustitución de coches por bicicletas <span><strong id="traffic-value">${settings.traffic}</strong> %</span><input name="traffic" type="range" min="0" max="100" value="${settings.traffic}"><span class="range-caption"><span>0 % · Tráfico original</span><span>100 % · Solo bicicletas</span></span></label><label class="field">Comportamiento de los ciclistas<select name="behavior">${selectOptions([['NORMAL','Normal'],['BREAKLAWS','Ignorar normas'],['AGRESSIVE','Agresivo']],settings.behavior)}</select></label><div class="notice">Los cambios se guardan en tu navegador. Exporta el INI para revisarlo en el PC; el juego todavía no recibe cambios desde esta app.</div></section></div><div class="action-bar"><button class="btn primary" type="submit">${icon('check')} Guardar configuración</button><button class="btn ghost" type="button" data-action="export-ini">${icon('download')} Exportar INI</button><span class="saved-label">Perfil local · Sin sincronización con GTA V</span></div></form><section class="card form-card" style="margin-top:22px"><h2>${icon('upload')} Tu archivo GTBikeVConfig.ini</h2><p>Importa tu archivo para cargar las opciones compatibles y conservar las demás claves al exportar.</p><button class="btn" data-action="import-ini">Importar INI</button><span class="badge-demo" id="ini-name">${iniName?escape(iniName):'Ningún archivo importado'}</span><p class="import-meta">Documents / Rockstar Games / GTA V / ModSettings / GTBikeVConfig.ini</p>${iniText?'<pre class="ini-preview" id="ini-preview"></pre>':''}</section>`;}
function botFields(bots){return bots.map((b,i)=>`<label class="field">Compañero ${i+1}<select name="bot${i}">${selectOptions([[0,'Aleatorio'],[1,'Compañero'],[2,'Escalador'],[3,'Sprinter'],[4,'Contrarreloj']],b)}</select></label>`).join('');}
function training(){return `${heading('DALE SENTIDO A CADA VATIO','Entrena con <em>intención.</em>','Elige una sesión, ajusta tu objetivo y encuentra tu siguiente nivel.')}<div class="training-grid"><section><div class="workout-list">${workouts.map((w,i)=>`<button class="workout-item ${i===activeWorkout?'selected':''}" data-action="workout" data-id="${i}" aria-pressed="${i===activeWorkout}"><span class="workout-index">0${i+1}</span><div><h3>${w.name}</h3><p>${w.tags}${w.minutes?' · '+w.minutes+' min':''}</p></div>${icon(i===activeWorkout?'check':'arrow')}</button>`).join('')}</div><div class="notice">Sesiones de demostración basadas en tu FTP de ${settings.ftp} W. Los intervalos cambian el objetivo ERG automáticamente; el control del rodillo físico requiere el puente con Windows.</div></section>${workoutPanel()}</div><section class="card training-chart"><div class="card-header"><div><h2>Tu sesión en marcha</h2><span class="tiny">${session.seconds?'Potencia simulada registrada':'Inicia para registrar tu primera pedalada'}</span></div><span class="pill">SIMULACIÓN</span></div><div class="chart-wrap" id="live-chart">${chart(session.points)}</div></section>`;}
function currentActivities(){const list=activities.length?activities:demoActivities;const limit=filter==='week'?7:filter==='month'?30:Infinity;return list.filter(a=>Date.now()-new Date(a.date).getTime()<limit*864e5).sort((a,b)=>new Date(b.date)-new Date(a.date));}
function history(){const list=currentActivities();const total=list.reduce((s,a)=>s+a.distance,0),seconds=list.reduce((s,a)=>s+a.seconds,0),maxP=Math.max(0,...list.map(a=>a.maxPower||0));return `${heading('EL CAMINO QUE LLEVAS','Tu esfuerzo <em>deja huella.</em>','Vuelve a tus recorridos. Descubre hasta dónde has llegado.',`<button class="btn primary" data-action="import-fit">${icon('upload')} Importar FIT</button>`)}<div class="notice" style="margin-top:0">${activities.length?'Tus actividades se guardan solo en este navegador. Puedes descargar un resumen CSV de cada una.':'Estás viendo actividades de ejemplo. Importa un FIT o guarda una sesión demo para comenzar tu historial.'}</div><div class="metric-grid history-summary">${metric('Distancia total',fmt(total,1),'km','bike',list.length+' actividades')}${metric('Tiempo en la bici',fmt(seconds/3600,1),'h','clock','En el período seleccionado')}${metric('Mejor potencia',fmt(maxP),'W','power','Pico registrado')}${metric('Desnivel total',fmt(list.reduce((s,a)=>s+a.ascent,0)),'m','mountain','Metros de ascenso')}</div><div class="history-top"><span class="section-title">Tus actividades <span class="badge-demo">${list.length}</span></span><div class="segmented" aria-label="Período">${[['week','Semana'],['month','Mes'],['all','Todo']].map(([id,label])=>`<button class="${filter===id?'active':''}" data-action="filter" data-id="${id}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div></div><div class="card table-scroll"><table class="activity-table"><thead><tr><th>ACTIVIDAD</th><th>DISTANCIA</th><th>TIEMPO</th><th>POTENCIA MEDIA</th><th></th></tr></thead><tbody>${list.map(a=>`<tr><td><button data-action="activity" data-id="${escape(a.id)}"><span class="ride-icon">${icon('bike')}</span>${escape(a.name)}<small>${date(a.date)} · ${a.demo?'Demo':a.imported?'FIT importado':'Sesión local'}</small></button></td><td>${fmt(a.distance,1)} km</td><td>${time(a.seconds)}</td><td>${a.power===null?'—':fmt(a.power)+' W'}</td><td><button data-action="activity" data-id="${escape(a.id)}" aria-label="Ver ${escape(a.name)}">↗</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No hay actividades en este período.</td></tr>'}</tbody></table></div><div class="records"><div class="record"><p class="eyebrow">TU RUTA MÁS LARGA</p><strong>${fmt(Math.max(0,...list.map(a=>a.distance)),1)} <small>km</small></strong><p>Récord del período</p></div><div class="record"><p class="eyebrow">TU MEJOR POTENCIA MEDIA</p><strong>${fmt(Math.max(0,...list.map(a=>a.power||0)))} <small>W</small></strong><p>Promedio de actividad</p></div><div class="record"><p class="eyebrow">TU MAYOR ASCENSO</p><strong>${fmt(Math.max(0,...list.map(a=>a.ascent)))} <small>m</small></strong><p>En una sola ruta</p></div></div>`;}
function render(){page=location.hash.slice(1)||'dashboard';if(!['dashboard','training','history','settings'].includes(page))page='dashboard';const names={dashboard:'Dashboard',training:'Entrenamiento',history:'Historial',settings:'Configuración'};$('#navigation').innerHTML=Object.entries(names).map(([id,label])=>`<a class="nav-link ${page===id?'active':''}" href="#${id}" ${page===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span>${page===id?'<span class="nav-dot"></span>':''}</a>`).join('');$('#crumb').textContent=names[page];$('#main').innerHTML=({dashboard,training,history,settings:configuration}[page])();if($('#ini-preview'))$('#ini-preview').textContent=iniText;bridgeUi?.afterRender();}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
function collectSettings(){const form=$('#settings-form');if(!form)return true;if(!form.reportValidity())return false;const f=new FormData(form);settings={...settings,weight:Number(f.get('weight')),ftp:Number(f.get('ftp')),difficulty:Number(f.get('difficulty')),resistance:f.has('resistance'),bike:f.get('bike'),traffic:Number(f.get('traffic')),behavior:f.get('behavior'),bots:Array.from({length:Number(f.get('botCount'))},(_,i)=>Number(f.get('bot'+i)))};return persist('gtbv-settings',settings);}
function showSensor(id){const d=devices.find(x=>x[0]===id);modal(`<p class="eyebrow">CONFIGURACIÓN DEL PC</p><h2>${d[1]}</h2><p>Indica el dispositivo que GTBikeV debe buscar. Estos valores se incluyen al exportar el INI.</p><form id="sensor-form" data-id="${id}"><label class="field">Identificador ANT+<input name="ant" type="number" min="0" max="65535" step="1" required value="${escape(settings.devices[d[2]])}"></label><p>0 = primer dispositivo encontrado · 65535 = desactivado.</p><label class="field">Dirección Bluetooth LE<input name="ble" value="${escape(settings.devices[d[3]])}" pattern="0|([0-9A-Fa-f]{2}:){5}[0-9A-Fa-f]{2}" required maxlength="17" placeholder="0 o AA:BB:CC:DD:EE:FF"></label><p>0 = automático · FF:FF:FF:FF:FF:FF = desactivado.</p><button class="btn primary" type="submit">Guardar sensor</button></form>`);}
function connection(){modal(`<p class="eyebrow">TU COMPAÑERO DE RUTA</p><h2>Conectemos los dos mundos.</h2><p>Esta versión funciona como prototipo interactivo. Puedes probar sesiones, preparar tu configuración e importar actividades.</p><div class="status-line"><span>Interfaz Companion</span><b style="color:#718e46">Disponible</b></div><div class="status-line"><span>Puente en Windows</span><b>Pendiente de implementar</b></div><div class="status-line"><span>Conexión con GTA V</span><b>Sin conexión</b></div><p>Para recibir telemetría y enviar órdenes desde Android necesitamos un puente local en el PC. Importar el INI permite preparar ajustes, pero no controla el juego en vivo.</p><a class="btn primary" href="https://www.gtbikev.com/support/" target="_blank" rel="noopener">Ver documentación oficial ↗</a>`);}
function activityDetails(id){const a=[...activities,...demoActivities].find(a=>a.id===id);if(!a)return;modal(`<p class="eyebrow">${a.demo?'ACTIVIDAD DEMO':a.imported?'ACTIVIDAD FIT':'ACTIVIDAD LOCAL'} · ${date(a.date)}</p><h2>${escape(a.name)}</h2><div class="inline-stats"><div><strong>${fmt(a.distance,1)}</strong><small>kilómetros</small></div><div><strong>${time(a.seconds)}</strong><small>tiempo</small></div><div><strong>${a.power===null?'—':fmt(a.power)}</strong><small>vatios medios</small></div></div>${a.points?.some(p=>p.p!==null)?chart(a.points):'<p>Este archivo no contiene datos de potencia.</p>'}<p>Ascenso: ${fmt(a.ascent)} m · Pico de potencia: ${fmt(a.maxPower)} W</p><button class="btn primary" data-action="export-activity" data-id="${escape(a.id)}">${icon('download')} Descargar resumen CSV</button>`);}
function finish(){if(!session.seconds)return;const p=session.points;const a={id:activityId(),name:workouts[activeWorkout].name+' · Los Santos',date:session.started,distance:session.distance,seconds:session.seconds,ascent:Math.round(session.ascent),power:Math.round(p.reduce((s,x)=>s+x.p,0)/p.length),maxPower:Math.max(...p.map(x=>x.p)),points:p.filter((_,i)=>i%Math.max(1,Math.ceil(p.length/600))===0),demo:true};const next=[a,...activities];if(!persist('gtbv-activities',next))return;activities=next;session={state:'idle',seconds:0,distance:0,ascent:0,energy:0,points:[],started:null};render();toast('Sesión demo guardada. Ya puedes verla en tu historial.');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;
  if(action==='close')$('#modal').close();
  if(action==='settings')location.hash='settings';
  if(action==='connection')connection();
  if(action==='route')modal(`<p class="eyebrow">EXPLORA LOS SANTOS</p><h2>Los Santos Coastal Loop</h2><p>Un circuito ilustrativo de 32,6 km y 326 m de ascenso, entre la costa de Vespucci y las calles de Los Santos.</p>${map()}<p>La ruta es una vista de demostración. No representa coordenadas o navegación real del juego.</p><button class="btn primary" data-action="close">Volver al dashboard</button>`);
  if(action==='zoom-in'||action==='zoom-out'){zoom=Math.max(1,Math.min(2,zoom+(action==='zoom-in'?.2:-.2)));document.querySelectorAll('#map-content').forEach(m=>m.style.transform=`scale(${zoom})`);}
  if(action==='erg'){erg=!erg;if(erg&&session.state==='running')blockTarget();document.querySelectorAll('[data-action="erg"]').forEach(x=>x.setAttribute('aria-checked',String(erg)));toast(erg?'ERG demo activado':'ERG demo desactivado');}
  if(action==='target-up'||action==='target-down'){target=Math.max(50,Math.min(600,target+(action==='target-up'?5:-5)));document.querySelectorAll('[data-live="target"]').forEach(x=>x.textContent=target);}
  if(action==='session'){if(session.state==='running'){session.state='paused';}else{session.state='running';session.started??=new Date().toISOString();}render();}
  if(action==='finish')finish();
  if(action==='workout'){if(session.seconds){toast('Finaliza la sesión actual antes de cambiar de entrenamiento.');return;}activeWorkout=Number(id);target=Math.round(settings.ftp*workouts[activeWorkout].ratio);render();toast('Entrenamiento seleccionado');}
  if(action==='sensor'){if(collectSettings())showSensor(id);}
  if(action==='filter'){filter=id;render();}
  if(action==='activity')activityDetails(id);
  if(action==='export-activity'){const a=[...activities,...demoActivities].find(a=>a.id===id);const cell=v=>'"'+String(v).replaceAll('"','""')+'"';download('gtbikev-resumen.csv','\uFEFF'+[['actividad','fecha','distancia_km','tiempo_s','potencia_media_w','potencia_max_w','ascenso_m','demo'],[a.name,a.date,a.distance.toFixed(2),a.seconds,a.power??'',a.maxPower,a.ascent,a.demo?'sí':'no']].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
  if(action==='import-fit')$('#fit-file').click();
  if(action==='import-ini')$('#ini-file').click();
  if(action==='export-ini'){if(!collectSettings())return;download(iniText?'GTBikeVConfig.ini':'GTBikeVConfig-parcial.ini',patchIni(iniText||'; Plantilla parcial generada por Companion. Revisar y combinar con el INI del mod.\n',settingsToIni(settings)));toast(iniText?'INI descargado. Revisa los cambios antes de reemplazar el archivo.':'Plantilla parcial descargada; combínala con tu INI existente.');}
});
document.addEventListener('input',e=>{if(e.target.name==='difficulty')$('#difficulty-value').textContent=e.target.value;if(e.target.name==='traffic')$('#traffic-value').textContent=e.target.value;});
document.addEventListener('change',e=>{if(e.target.name==='botCount'){const count=Number(e.target.value);const current=Array.from(document.querySelectorAll('#bot-fields select')).map(x=>Number(x.value));$('#bot-fields').innerHTML=botFields(Array.from({length:count},(_,i)=>current[i]??0));}});
document.addEventListener('submit',e=>{if(e.target.id==='settings-form'){e.preventDefault();if(collectSettings())toast('Configuración guardada en este navegador.');}if(e.target.id==='sensor-form'){e.preventDefault();const f=new FormData(e.target),d=devices.find(x=>x[0]===e.target.dataset.id);settings.devices[d[2]]=String(Number(f.get('ant')));settings.devices[d[3]]=String(f.get('ble')).toUpperCase();if(persist('gtbv-settings',settings)){$('#modal').close();render();toast('Preferencias del sensor guardadas.');}}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});
$('#ini-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1024*1024)throw Error('El INI supera el límite de 1 MB.');const text=await file.text();if(!/^\s*\[(MAIN|USER|DEVICES)\]/mi.test(text))throw Error('No se reconocen las secciones de configuración de GTBikeV.');const s=applyIni(text,settings);if(persist('gtbv-settings',s)&&persist('gtbv-ini',text)&&persist('gtbv-ini-name',file.name)){settings=s;iniText=text;iniName=file.name;render();toast('INI importado. Se cargaron las opciones compatibles.');}}catch(err){toast(err.message);}finally{e.target.value='';}});
$('#fit-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;toast('Leyendo actividad FIT…');try{if(file.size>20*1024*1024)throw Error('El archivo supera el límite de 20 MB.');const {parseActivity}=await import('./fit-import.js');const a={...parseActivity(await file.arrayBuffer(),file.name),id:activityId()};const next=[a,...activities];if(persist('gtbv-activities',next)){activities=next;filter='all';location.hash='history';render();toast('Actividad FIT importada. Tus datos se quedan en este navegador.');}}catch(err){toast(err.message||'No se pudo leer el archivo FIT.');}finally{e.target.value='';}});
function blockTarget(){if(!erg)return;const planned=intervalTarget(activeWorkout,session.seconds,settings.ftp);if(planned!==null)target=planned;}
let previousTick=performance.now();
setInterval(()=>{if(bridgeUi?.local)return;const now=performance.now();const dt=(now-previousTick)/1000;previousTick=now;let p=186+Math.round(Math.sin(now/1800)*11),speed=32.4+Math.sin(now/3000)*1.1,cadence=88+Math.round(Math.sin(now/2100)*3),heart=142+Math.round(Math.sin(now/4000)*3);
 if(session.state==='running'){const previousBlock=currentBlock(activeWorkout,session.seconds);session.seconds+=dt;const nextBlock=currentBlock(activeWorkout,session.seconds);if(session.points.length===0||previousBlock!==nextBlock)blockTarget();p=erg?target+Math.round(Math.sin(now/1800)*8):p;session.distance+=speed*dt/3600;session.ascent+=.05*dt;session.energy+=p*dt/1000;session.points.push({t:Math.round(session.seconds),p});if(session.points.length>7200)session.points=session.points.filter((_,i)=>i%2===0);const w=workouts[activeWorkout];if(w.minutes&&session.seconds>=w.minutes*60){finish();toast('Entrenamiento completado y guardado en el historial.');return;}}
 if(session.state==='paused'){p=0;speed=0;cadence=0;}
 const zone=p/settings.ftp;const zoneLabel=zone<=.55?'Z1 · Recuperación':zone<=.75?'Z2 · Resistencia':zone<=.9?'Z3 · Tempo':zone<=1.05?'Z4 · Umbral':zone<=1.2?'Z5 · VO₂ máx.':'Z6 · Anaeróbico';if($('#power-zone'))$('#power-zone').textContent=zoneLabel;
 if(page==='dashboard'||page==='training'){const values={power:p,speed:fmt(speed,1),cadence,heart,elapsed:time(session.seconds),distance:fmt(session.distance,1),ascent:Math.round(session.ascent),target};for(const [key,value]of Object.entries(values))document.querySelectorAll(`[data-live="${key}"]`).forEach(el=>el.textContent=value);if(session.state==='running'){if($('#live-chart'))$('#live-chart').innerHTML=chart(session.points.filter((_,i)=>i%Math.max(1,Math.ceil(session.points.length/200))===0));const w=workouts[activeWorkout];const pct=w.minutes?Math.min(100,session.seconds/(w.minutes*60)*100):0;if($('#workout-progress'))$('#workout-progress').style.width=pct+'%';document.querySelectorAll('.workout-bars span').forEach((el,i)=>el.classList.toggle('current',i===currentBlock(activeWorkout,session.seconds)));const chartLabel=document.querySelector('#live-chart')?.closest('section')?.querySelector('.card-header .tiny');if(chartLabel)chartLabel.textContent='Potencia · Sesión actual';const stop=document.querySelector('[data-action="finish"]');if(stop)stop.disabled=false;}}
},1000);
render();

bridgeUi=new BridgeUI({render,toast,modal,chart,time,getTarget:()=>target,getSettings:()=>settings,collectSettings,setConfig:(text)=>{iniText=text;iniName='GTBikeVConfig.ini (PC)';settings=applyIni(text,settings);persist('gtbv-settings',settings);},addActivity:(a)=>{const next=[a,...activities.filter(item=>item.id!==a.id)];if(!persist('gtbv-activities',next))throw Error('No se pudo guardar la actividad.');activities=next;}});
